[{"order":1,"type":"heading","text":"Angular Custom Directives: Attribute and Structural Directives"},{"order":2,"type":"paragraph","text":"Angular directives are powerful tools for manipulating the DOM. They allow you to extend HTML by adding custom behavior to existing elements or creating entirely new ones. There are three types of directives: Components, Attribute directives, and Structural directives. This tutorial focuses on Attribute and Structural directives."},{"order":3,"type":"subheading","text":"Attribute Directives"},{"order":4,"type":"paragraph","text":"Attribute directives change the appearance or behavior of an existing element. They are applied to elements as if they were HTML attributes."},{"order":5,"type":"paragraph","text":"Example: Creating a Highlight Directive"},{"order":6,"type":"code","text":"import { Directive, ElementRef, HostListener, Input } from '@angular/core';

@Directive({
  selector: '[appHighlight]'
})
export class HighlightDirective {
  @Input('appHighlight') highlightColor: string;

  constructor(private el: ElementRef) { }

  @HostListener('mouseenter') onMouseEnter() {
    this.highlight(this.highlightColor || 'yellow');
  }

  @HostListener('mouseleave') onMouseLeave() {
    this.highlight(null);
  }

  private highlight(color: string) {
    this.el.nativeElement.style.backgroundColor = color;
  }
}"},{"order":7,"type":"paragraph","text":"Explanation:
- `@Directive({ selector: '[appHighlight]' })`:  This defines the directive and its selector.  The `[appHighlight]` selector means this directive will be applied to elements that have the `appHighlight` attribute.
- `@Input('appHighlight') highlightColor: string`: This allows you to pass a value to the directive via the `appHighlight` attribute. If no value is provided, it defaults to 'yellow'.
- `@HostListener('mouseenter')` and `@HostListener('mouseleave')`: These listen for mouse events and call the `onMouseEnter` and `onMouseLeave` methods respectively.
- `this.el.nativeElement.style.backgroundColor = color`: This line changes the background color of the element."},{"order":8,"type":"paragraph","text":"Usage in a template:"},{"order":9,"type":"code","text":"<p appHighlight="red">Highlight me!</p>
<p appHighlight>Highlight me with default color!</p>"},{"order":10,"type":"subheading","text":"Structural Directives"},{"order":11,"type":"paragraph","text":"Structural directives change the DOM layout by adding, removing, or replacing elements. They are prefixed with an asterisk `*`."},{"order":12,"type":"paragraph","text":"Example: Creating an `*appUnless` Directive"},{"order":13,"type":"code","text":"import { Directive, Input, TemplateRef, ViewContainerRef } from '@angular/core';

@Directive({
  selector: '[appUnless]'
})
export class UnlessDirective {
  private hasView = false;

  constructor(
    private templateRef: TemplateRef<any>,
    private viewContainer: ViewContainerRef
  ) { }

  @Input() set appUnless(condition: boolean) {
    if (!condition && !this.hasView) {
      this.viewContainer.createEmbeddedView(this.templateRef);
      this.hasView = true;
    } else if (condition && this.hasView) {
      this.viewContainer.clear();
      this.hasView = false;
    }
  }
}"},{"order":14,"type":"paragraph","text":"Explanation:
- `@Directive({ selector: '[appUnless]' })`: Defines the directive with the selector `[appUnless]`.
- `TemplateRef`: Represents the content inside the element where the directive is used (e.g., the content of the `<div>` in `<div *appUnless="condition">`).
- `ViewContainerRef`: Represents the container where the content will be rendered or removed.
- `@Input() set appUnless(condition: boolean)`: This is a setter for the `appUnless` input. When the condition changes, this setter is called.
- `this.viewContainer.createEmbeddedView(this.templateRef)`: Creates and inserts the content into the view container.
- `this.viewContainer.clear()`: Removes the content from the view container."},{"order":15,"type":"paragraph","text":"Usage in a template:"},{"order":16,"type":"code","text":"<div *appUnless="condition">This is displayed unless the condition is true.</div>"},{"order":17,"type":"paragraph","text":"In this example, the `<div>` and its content will only be rendered if the `condition` is false. This is the opposite of `*ngIf`."},{"order":18,"type":"subheading","text":"Key Differences"},{"order":19,"type":"bullet_point","text":"Attribute directives modify the appearance or behavior of an existing element."},{"order":20,"type":"bullet_point","text":"Structural directives change the DOM layout by adding, removing, or replacing elements."},{"order":21,"type":"bullet_point","text":"Structural directives are prefixed with an asterisk `*` in the template."},{"order":22,"type":"subheading","text":"Conclusion"},{"order":23,"type":"paragraph","text":"Custom directives are a powerful way to extend Angular's functionality and create reusable components. Understanding the difference between attribute and structural directives is crucial for building robust and maintainable Angular applications. Remember to always consider performance implications when manipulating the DOM, especially with structural directives."}]
